  <title>Support Contact Form</title>
  <style>
    :root {
      color-scheme: light;
      --bg: #f6f8fb;
      --card: #ffffff;
      --text: #162033;
      --muted: #64748b;
      --border: #dbe3ef;
      --primary: #2563eb;
      --primary-dark: #1d4ed8;
      --ring: rgba(37, 99, 235, 0.18);
      --shadow: 0 24px 70px rgba(15, 23, 42, 0.12);
    }

    * {
      box-sizing: border-box;
    }

    body {
      margin: 0;
      min-height: 100vh;
      font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      color: var(--text);
      background:
        radial-gradient(circle at top left, rgba(37, 99, 235, 0.14), transparent 32rem),
        linear-gradient(135deg, #f8fbff 0%, var(--bg) 52%, #eef4ff 100%);
    }

    .page-shell {
      display: grid;
      place-items: center;
      min-height: 100vh;
      padding: 48px 20px;
    }

    .support-card {
      width: min(100%, 560px);
      padding: 40px;
      background: rgba(255, 255, 255, 0.92);
      border: 1px solid rgba(219, 227, 239, 0.88);
      border-radius: 28px;
      box-shadow: var(--shadow);
      backdrop-filter: blur(16px);
    }

    .eyebrow {
      margin: 0 0 12px;
      color: var(--primary);
      font-size: 0.78rem;
      font-weight: 800;
      letter-spacing: 0.12em;
      text-transform: uppercase;
    }

    h1 {
      margin: 0;
      font-size: clamp(2rem, 5vw, 3rem);
      line-height: 1.05;
      letter-spacing: -0.05em;
    }

    .intro {
      margin: 16px 0 32px;
      color: var(--muted);
      font-size: 1rem;
      line-height: 1.65;
    }

    .contact-form {
      display: grid;
      gap: 20px;
    }

    .form-field {
      display: grid;
      gap: 8px;
    }

    label {
      font-size: 0.94rem;
      font-weight: 700;
    }

    input {
      width: 100%;
      min-height: 52px;
      padding: 0 16px;
      color: var(--text);
      font: inherit;
      background: #fbfdff;
      border: 1px solid var(--border);
      border-radius: 14px;
      outline: none;
      transition: border-color 180ms ease, box-shadow 180ms ease, background-color 180ms ease;
    }

    input::placeholder {
      color: #9aa8bc;
    }

    input:focus {
      background: #ffffff;
      border-color: var(--primary);
      box-shadow: 0 0 0 4px var(--ring);
    }

    .helper-text {
      margin: 0;
      color: var(--muted);
      font-size: 0.86rem;
      line-height: 1.45;
    }

    button {
      min-height: 54px;
      margin-top: 8px;
      color: #ffffff;
      font: inherit;
      font-weight: 800;
      background: linear-gradient(135deg, var(--primary), #3b82f6);
      border: 0;
      border-radius: 16px;
      cursor: pointer;
      box-shadow: 0 14px 28px rgba(37, 99, 235, 0.28);
      transition: transform 180ms ease, box-shadow 180ms ease, background 180ms ease;
    }

    button:hover {
      transform: translateY(-1px);
      background: linear-gradient(135deg, var(--primary-dark), var(--primary));
      box-shadow: 0 18px 34px rgba(37, 99, 235, 0.32);
    }

    button:focus-visible {
      outline: 4px solid var(--ring);
      outline-offset: 3px;
    }

    @media (max-width: 560px) {
      .support-card {
        padding: 28px;
        border-radius: 22px;
      }
    }
  </style>
</head>
<body>
  <div id="root"></div>

  <script>
    const fields = [
      {
        id: "full-name",
        label: "Full name",
        type: "text",
        name: "fullName",
        placeholder: "Jane Doe",
        required: true,
        autocomplete: "name"
      },
      {
        id: "email-address",
        label: "Email address",
        type: "email",
        name: "email",
        placeholder: "jane@example.com",
        required: true,
        autocomplete: "email"
      },
      {
        id: "phone-number",
        label: "Phone number",
        type: "tel",
        name: "phone",
        placeholder: "(555) 123-4567",
        required: false,
        autocomplete: "tel",
        helperText: "Optional. Use a country code and area code when applicable, for example +1 555 123 4567."
      }
    ];

    function Field({ id, label, helperText, ...inputProps }) {
      const describedBy = helperText ? `${id}-helper` : undefined;

      return `
        <div class="form-field">
          <label for="${id}">${label}</label>
          <input
            id="${id}"
            ${describedBy ? `aria-describedby="${describedBy}"` : ""}
            ${inputProps.required ? "required" : ""}
            type="${inputProps.type}"
            name="${inputProps.name}"
            placeholder="${inputProps.placeholder}"
            autocomplete="${inputProps.autocomplete}"
          >
          ${helperText ? `<p class="helper-text" id="${describedBy}">${helperText}</p>` : ""}
        </div>
      `;
    }

    function ContactForm() {
      return `
        <main class="page-shell">
          <section class="support-card" aria-labelledby="support-title">
            <p class="eyebrow">Support request</p>
            <h1 id="support-title">How can we help?</h1>
            <p class="intro">
              Share your contact details and our support team will get back to you with a clear next step.
            </p>
            <form class="contact-form" action="#" method="post">
              ${fields.map(Field).join("")}
              <button type="submit">Contact support</button>
            </form>
          </section>
        </main>
      `;
    }

    function App() {
      return ContactForm();
    }

    document.getElementById("root").innerHTML = App();
  </script>
</body>
</html>
